#include <bits/stdc++.h>
using namespace std;
int n; long long a[25];
unordered_map<long long,long long> memo[2];
long long solve(int p1,int p2,int mask,int turn){
  long long key=((long long)mask*(n+1)+p1)*(n+1)+p2;
  auto &mp=memo[turn];
  auto it=mp.find(key); if(it!=mp.end()) return it->second;
  bool can0=false,can1=false;
  for(int d=1;d<=4;d++){int c=p1+d; if(c<=n && !(mask>>c&1)){can0=true;break;}}
  for(int d=1;d<=4;d++){int c=p2+d; if(c<=n && !(mask>>c&1)){can1=true;break;}}
  if(!can0&&!can1) return mp[key]=0;
  long long res;
  if(turn==0){
    if(!can0) res=solve(p1,p2,mask,1);
    else{
      res=LLONG_MIN;
      for(int d=1;d<=4;d++){int c=p1+d; if(c<=n && !(mask>>c&1)){ res=max(res, a[c]+solve(c,p2,mask|(1<<c),1)); }}
    }
  } else {
    if(!can1) res=solve(p1,p2,mask,0);
    else{
      res=LLONG_MAX;
      for(int d=1;d<=4;d++){int c=p2+d; if(c<=n && !(mask>>c&1)){ res=min(res, -a[c]+solve(p1,c,mask|(1<<c),0)); }}
    }
  }
  return mp[key]=res;
}
