  int T; if(scanf("%d",&T)!=1) return 0;
  while(T--){
    scanf("%d",&n);
    for(int i=3;i<=n;i++) scanf("%lld",&a[i]);
    memo[0].clear(); memo[1].clear();
    int mask=(1<<1)|(1<<2);
    long long ans=solve(1,2,mask,0);
    printf("%lld\n",ans);
  }
  return 0;
}

