#include <bits/stdc++.h>
using namespace std;
static const int W=8, SZ=2*2*9*256;
static vector<long long> dp;
inline int IDX(int flag,int turn,int b,int mask){ return ((flag*2+turn)*9 + b)*256 + mask; }
long long solveCase(int n, const vector<long long>& a){
  if((int)dp.size()<W*SZ) dp.assign(W*SZ,0);
  for(int lo=n;lo>=1;--lo){
    int slot=lo&(W-1);
    long long* base=&dp[slot*SZ];
    for(int i=0;i<SZ;i++) base[i]=0;
    int maxb=min(8,n-lo);
    for(int b=maxb;b>=1;--b){
      int lim=1<<(b-1);
      for(int t=0;t<lim;t++){
        int mask=(1<<b)|(t<<1);
        for(int flag=0;flag<2;flag++){
          long long res[2]={0,0}; bool has[2]={false,false};
          for(int turn=0;turn<2;turn++){
            int m_off=(turn==flag)?0:b;
            int o_off=(turn==flag)?b:0;
            long long best=(turn==0)?LLONG_MIN:LLONG_MAX;
            for(int d=1;d<=4;d++){
              int c_off=m_off+d;
              if(lo+c_off>n) break;
              if(abs(c_off-o_off)>8) continue;
              if((mask>>c_off)&1) continue; // occupied (c_off<=8)
              int s=min(c_off,o_off);
              int nlo=lo+s;
              int mo=c_off-s, oo=o_off-s;
              int nflag=(mo==0)?turn:(1-turn);
              int nb=max(mo,oo);
              int nmask=0;
              for(int j=1;j<=8;j++) if((mask>>j)&1){int nj=j-s; if(nj>=1&&nj<=8) nmask|=1<<nj;}
              if(mo>=1) nmask|=1<<mo;
              if(oo>=1) nmask|=1<<oo;
              long long gain=a[lo+c_off];
              int slot2=nlo&(W-1);
              long long child=dp[slot2*SZ+IDX(nflag,1-turn,nb,nmask)];
              long long cand=(turn==0)?(gain+child):(-gain+child);
              if(turn==0){ if(cand>best) best=cand; } else { if(cand<best) best=cand; }
              has[turn]=true;
            }
            res[turn]=best;
          }
          if(!has[0]&&!has[1]){ res[0]=0;res[1]=0; }
          else if(!has[0]) res[0]=res[1];
          else if(!has[1]) res[1]=res[0];
          base[IDX(flag,0,b,mask)]=res[0];
          base[IDX(flag,1,b,mask)]=res[1];
        }
      }
    }
  }
  return dp[(1&(W-1))*SZ + IDX(0,0,1,2)];
}
