  int T; if(scanf("%d",&T)!=1) return 0;
  while(T--){
    int n; scanf("%d",&n);
    vector<long long> a(n+1,0);
    for(int i=3;i<=n;i++) scanf("%lld",&a[i]);
    printf("%lld\n", solveCase(n,a));
  }
  return 0;
}

