int Bn; long long Ba[30];
unordered_map<long long,long long> memo[2];
long long bf(int p1,int p2,int mask,int turn){
  long long key=((long long)mask*(Bn+1)+p1)*(Bn+1)+p2;
  auto &mp=memo[turn]; auto it=mp.find(key); if(it!=mp.end()) return it->second;
  bool c0=false,c1=false;
  for(int d=1;d<=4;d++){int c=p1+d; if(c<=Bn&&!(mask>>c&1)){c0=true;break;}}
  for(int d=1;d<=4;d++){int c=p2+d; if(c<=Bn&&!(mask>>c&1)){c1=true;break;}}
  if(!c0&&!c1) return mp[key]=0;
  long long res;
  if(turn==0){ if(!c0)res=bf(p1,p2,mask,1); else{res=LLONG_MIN;for(int d=1;d<=4;d++){int c=p1+d;if(c<=Bn&&!(mask>>c&1))res=max(res,Ba[c]+bf(c,p2,mask|(1<<c),1));}} }
  else { if(!c1)res=bf(p1,p2,mask,0); else{res=LLONG_MAX;for(int d=1;d<=4;d++){int c=p2+d;if(c<=Bn&&!(mask>>c&1))res=min(res,-Ba[c]+bf(p1,c,mask|(1<<c),0));}} }
  return mp[key]=res;
}
