using namespace std;
int n;
set<pair<int,unsigned long long>> reach[13][13][2];
// state: positions p1,p2, mask over cells 1..n, turn
void dfs(int p1,int p2,unsigned long long mask,int turn){
  auto key=make_pair(p1,make_pair(p2,make_pair(turn,mask)));
  int mn=min(p1,p2),mx=max(p1,p2);
  unsigned long long rel=0; for(int c=mn;c<=mx;c++) if(mask>>c&1) rel|=1ULL<<(c-mn);
  if(reach[mn][mx][turn].count({p1,rel})) return; // dedup rough
  reach[mn][mx][turn].insert({p1,rel});
  bool c0=false,c1=false; for(int d=1;d<=4;d++){int c=p1+d;if(c<=n&&!(mask>>c&1)){c0=true;break;}} for(int d=1;d<=4;d++){int c=p2+d;if(c<=n&&!(mask>>c&1)){c1=true;break;}}
  if(!c0&&!c1) return;
  if(turn==0){ if(!c0)dfs(p1,p2,mask,1); else for(int d=1;d<=4;d++){int c=p1+d;if(c<=n&&!(mask>>c&1))dfs(c,p2,mask|(1ULL<<c),1);} }
  else { if(!c1)dfs(p1,p2,mask,0); else for(int d=1;d<=4;d++){int c=p2+d;if(c<=n&&!(mask>>c&1))dfs(p1,c,mask|(1ULL<<c),0);} }
}
