    if(reach[mn][mx][t].empty())continue;
    // collect distinct relative masks
    set<unsigned long long> rels; for(auto&pr:reach[mn][mx][t]) rels.insert(pr.second);
    printf("(%d,%d,t%d) #rel=%d:",mn,mx,t,(int)rels.size());
    int cnt=0; for(auto r:rels){ if(cnt++<6){printf(" [");for(int c=0;c<=mx-mn;c++)if(r>>c&1)printf("%d,",mn+c);printf("]");} }
    printf("\n");
  }
  return 0;
}

