#include <bits/stdc++.h>
using namespace std;
int n; long long a[200];
struct Key{int p1,p2,lo; unsigned long long mask; bool operator==(const Key&o)const{return p1==o.p1&&p2==o.p2&&lo==o.lo&&mask==o.mask;}};
struct H{size_t operator()(const Key&k)const{return (((size_t)k.p1*1000003+k.p2)*1000003+k.lo)+(size_t)(k.mask*2654435761ULL);}};
unordered_map<Key,long long,H> memo[2];
long long solve(int p1,int p2,unsigned long long mask,int lo,int turn,int cap){
  Key k{p1,p2,lo,mask}; auto it=memo[turn].find(k); if(it!=memo[turn].end())return it->second;
  int hi=max(p1,p2); auto freeCell=[&](int c)->bool{ if(c<lo||c>hi)return true; return !((mask>>(c-lo))&1ULL); };
  auto can=[&](int p,int o)->bool{for(int d=1;d<=4;d++){int c=p+d;if(c>n)break;if(abs(c-o)>cap)continue;if(freeCell(c))return true;}return false;};
  bool c0=can(p1,p2),c1=can(p2,p1); if(!c0&&!c1)return memo[turn][k]=0; long long res;
  if(turn==0){ if(!c0)res=solve(p1,p2,mask,lo,1,cap); else{res=LLONG_MIN; for(int d=1;d<=4;d++){int c=p1+d;if(c>n)break;if(abs(c-p2)>cap)continue;if(!freeCell(c))continue;
    int nlo=min(c,p2),nhi=max(c,p2);unsigned long long nm=0; for(int x=nlo;x<=nhi;x++){bool o=(x==c||x==p2)||(x!=c&&x!=p2&&x>=lo&&x<=hi&&((mask>>(x-lo))&1ULL));if(o)nm|=1ULL<<(x-nlo);} res=max(res,a[c]+solve(c,p2,nm,nlo,1,cap));}}}
  else { if(!c1)res=solve(p1,p2,mask,lo,0,cap); else{res=LLONG_MAX; for(int d=1;d<=4;d++){int c=p2+d;if(c>n)break;if(abs(c-p1)>cap)continue;if(!freeCell(c))continue;
    int nlo=min(p1,c),nhi=max(p1,c);unsigned long long nm=0; for(int x=nlo;x<=nhi;x++){bool o=(x==p1||x==c)||(x!=p1&&x!=c&&x>=lo&&x<=hi&&((mask>>(x-lo))&1ULL));if(o)nm|=1ULL<<(x-nlo);} res=min(res,-a[c]+solve(p1,c,nm,nlo,0,cap));}}}
  return memo[turn][k]=res;
}
